import {cleanupFiles,purgeAttachment} from '../core/storage-cleanup.js?v=20261111-v15a';
export function install(ctx){
 const size=n=>Number(n)>=1e6?(Number(n)/1e6).toLocaleString('pt-BR',{maximumFractionDigits:2})+' MB':Math.max(0,Number(n)/1000).toLocaleString('pt-BR',{maximumFractionDigits:1})+' KB';
 async function storageManager(){
  if(!ctx.profile?.active||!ctx.profile.is_owner)return ctx.toast('Área exclusiva do Mestre Criador.');
  const d=ctx.modal('Gerenciar arquivos armazenados',`<p>Escolha os anexos antigos que deseja remover. A exclusão definitiva libera o espaço do arquivo; arquivar apenas o oculta. Pedidos, recibos e lançamentos financeiros permanecem no histórico.</p><div class="grid2"><label class="field">Idade do arquivo<select id="cleanup-age"><option value="90">Mais de 90 dias</option><option value="180">Mais de 180 dias</option><option value="365">Mais de um ano</option><option value="30">Mais de 30 dias</option><option value="0">Todas as datas</option></select></label><label class="field">Situação<select id="cleanup-state"><option value="all">Todos os arquivos</option><option value="archived">Somente arquivados</option><option value="active">Somente ativos</option></select></label><label class="field span2">Buscar nome ou registro relacionado<input type="search" id="cleanup-search" maxlength="150"></label></div><p id="cleanup-status" role="status" aria-live="polite">Carregando…</p><div id="cleanup-list"></div><div class="form-actions"><button class="secondary" data-close>Fechar</button><button class="danger" id="cleanup-review" disabled>Revisar exclusão dos selecionados</button></div><p class="muted helper">Esta tela gerencia anexos privados cadastrados no Avelon. Não apaga código do GitHub, arquivos do seu aparelho ou registros financeiros.</p>`,{wide:true});
  let records=[],selected=new Set();const status=d.querySelector('#cleanup-status'),list=d.querySelector('#cleanup-list'),review=d.querySelector('#cleanup-review');
  async function load(){try{records=await ctx.rpc('owner_attachment_files');if(!Array.isArray(records))throw Error('Não foi possível consultar os arquivos.');selected.clear();draw()}catch(e){status.textContent=e.message;list.replaceChildren();review.disabled=true}}
  function draw(){const shown=cleanupFiles(records,{days:Number(d.querySelector('#cleanup-age').value),state:d.querySelector('#cleanup-state').value,query:d.querySelector('#cleanup-search').value});const visible=shown.slice(0,200);selected=new Set([...selected].filter(id=>visible.some(f=>f.id===id)));list.innerHTML=visible.length?`<div class="table-wrap cleanup-table"><table><thead><tr><th>Selecionar</th><th>Arquivo / vínculo</th><th>Data</th><th>Tamanho</th><th>Situação</th><th>Consultar</th></tr></thead><tbody>${visible.map(f=>`<tr><td><input type="checkbox" data-cleanup-id="${f.id}" aria-label="Selecionar ${ctx.esc(f.name)}" ${selected.has(f.id)?'checked':''}></td><td><strong>${ctx.esc(f.name)}</strong><small>${ctx.esc(({quote:'Pedido',entry:'Financeiro',receipt:'Recibo'}[f.parent_type]||'Registro')+' · '+(f.reference||''))}</small></td><td>${ctx.date(f.created_at)}</td><td>${size(f.byte_size)}</td><td>${f.purge_pending?'Exclusão pendente':f.archived?'Arquivado':f.state==='uploading'?'Envio incompleto':'Ativo'}${!f.file_present?' · arquivo ausente':''}</td><td>${f.file_present?`<button class="secondary small" data-cleanup-download="${f.id}">Baixar</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Nenhum arquivo corresponde aos filtros. Para conferir os anexos recentes, selecione Todas as datas.</p>';
   list.querySelectorAll('[data-cleanup-id]').forEach(el=>el.onchange=()=>{if(el.checked){if(selected.size>=50){el.checked=false;ctx.toast('Selecione até 50 arquivos por vez.');return}selected.add(el.dataset.cleanupId)}else selected.delete(el.dataset.cleanupId);summary(shown.length)});
   list.querySelectorAll('[data-cleanup-download]').forEach(el=>el.onclick=async()=>{el.disabled=true;try{const f=records.find(x=>x.id===el.dataset.cleanupDownload);await ctx.downloadStoredFile({...f,original_name:f.name});status.textContent='Download iniciado. Confira o arquivo antes de excluir.'}catch(e){status.textContent=e.message}finally{el.disabled=false}});summary(shown.length);
  }
  function summary(count){const chosen=records.filter(f=>selected.has(f.id));status.textContent=`${count} arquivos encontrados${count>200?' · mostrando os primeiros 200; refine os filtros':''}. ${chosen.length} selecionados · ${size(chosen.filter(f=>f.file_present).reduce((s,f)=>s+Number(f.byte_size),0))} para liberar (estimativa).`;review.disabled=!chosen.length;}
  for(const id of ['cleanup-age','cleanup-state'])d.querySelector('#'+id).onchange=draw;d.querySelector('#cleanup-search').oninput=draw;
  review.onclick=()=>{const chosen=records.filter(f=>selected.has(f.id));if(!chosen.length)return;const c=ctx.modal('Confirmar exclusão definitiva',`<p>Os arquivos abaixo serão apagados do armazenamento e não poderão ser restaurados pelo sistema. Se precisar, baixe uma cópia antes. Os registros relacionados e a auditoria serão preservados.</p><ul class="cleanup-confirm-list">${chosen.map(f=>`<li><strong>${ctx.esc(f.name)}</strong> · ${size(f.byte_size)}<small>${ctx.esc(f.reference||'')}</small></li>`).join('')}</ul><label class="inline-check"><input type="checkbox" id="cleanup-confirm-check"> Conferi a lista e entendo que a exclusão é definitiva.</label><p id="cleanup-progress" role="status" aria-live="polite"></p><div class="form-actions"><button class="secondary" data-close>Cancelar</button><button class="danger" id="cleanup-confirm-delete" disabled>Excluir definitivamente ${chosen.length} arquivo(s)</button></div>`,{wide:true});
   const button=c.querySelector('#cleanup-confirm-delete'),check=c.querySelector('#cleanup-confirm-check'),progress=c.querySelector('#cleanup-progress');check.onchange=()=>button.disabled=!check.checked;
   button.onclick=async()=>{if(!check.checked)return;button.disabled=true;check.disabled=true;c.querySelectorAll('[data-close]').forEach(b=>b.disabled=true);let done=0,errors=[];
    for(const f of chosen){progress.textContent=`Excluindo ${done+errors.length+1} de ${chosen.length}…`;try{await purgeAttachment(ctx,f.id);done++}catch(e){errors.push(f.name+': '+e.message)}}
    progress.textContent=`${done} arquivo(s) excluído(s).`+(errors.length?' Não concluídos: '+errors.join(' | '):' O histórico dos registros foi preservado.');c.querySelectorAll('[data-close]').forEach(b=>{b.disabled=false;b.textContent='Fechar'});button.remove();check.closest('label').hidden=true;if(d.isConnected)await load();if(ctx.current==='usage')ctx.refreshUsage?.();
   };
  };
  await load();
 }
 Object.assign(ctx,{storageManager});
}
